// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.workerimport timber.log.Timberimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport com.roshan.persona.automation.engine.AutomationEngineimport com.roshan.persona.automation.engine.FireResultimport com.roshan.persona.automation.model.AutomationTriggerimport dagger.hilt.EntryPointimport dagger.hilt.InstallInimport dagger.hilt.android.EntryPointAccessorsimport dagger.hilt.components.SingletonComponentimport java.time.DayOfWeekimport java.time.LocalDateTimeimport java.time.ZoneId/** * NOUS — Automation Worker (Module 8). * * REAL [CoroutineWorker] that fires when an [AutomationTrigger] fires. * * ## How it gets scheduled * * [com.roshan.persona.automation.scheduler.AutomationScheduler] enqueues * this worker via WorkManager with one of four trigger kinds: * *   - [TRIGGER_KIND_TIME]           — fired by `PeriodicWorkRequest` (24h *                                     interval). Worker checks `daysOfWeek` *                                     before firing. *   - [TRIGGER_KIND_EVENT]          — fired by `OneTimeWorkRequest` after a *                                     dynamic BroadcastReceiver received a *                                     matching system broadcast. *   - [TRIGGER_KIND_STATE]          — same as event, but for state triggers. *   - [TRIGGER_KIND_COMPOUND_CHILD] — fired when a child of a *                                     [AutomationTrigger.CompoundTrigger] *                                     fires. Worker calls *                                     `fireRule(parentId, sourceTrigger)`. * * ## How it accesses the engine * * This worker is constructed by WorkManager (not Hilt). To access the * `@Singleton`-scoped [AutomationEngine], we use [EntryPointAccessors] — * the standard Hilt pattern for accessing singletons from non-Hilt-managed * code. This avoids the need to wire a `HiltWorkerFactory` into the * `Application` class. * * ## What the worker does * * When WorkManager fires the worker: *   1. Read ruleId + triggerKind from input data. *   2. Look up the rule via [AutomationEngine.getRule]. *      - If not found / disabled → return `Result.success()` (rule was *        deleted/disabled after scheduling). *   3. For [TRIGGER_KIND_TIME] — check if today's `DayOfWeek` is in the *      trigger's `daysOfWeek` set. If not → return `Result.success()` *      without firing (the worker will fire again tomorrow at the same time). *   4. Call [AutomationEngine.fireRule] (or `manuallyFire` for compound *      children). *   5. Return `Result.success()` regardless of action outcome — failures *      are recorded in the engine, not propagated as WorkManager failures *      (we don't want WorkManager to retry the trigger; it'll fire again *      on the next cycle). * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */class AutomationWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    companion object {        private const val TAG = "AutomationWorker"        /** WorkManager input key for the rule ID to fire. */        const val KEY_RULE_ID = "automation_rule_id"        /**         * WorkManager input key for the trigger kind.         *         * One of:         *   - [TRIGGER_KIND_TIME]         *   - [TRIGGER_KIND_EVENT]         *   - [TRIGGER_KIND_STATE]         *   - [TRIGGER_KIND_COMPOUND_CHILD]         */        const val KEY_TRIGGER_KIND = "automation_trigger_kind"        /** Time-based trigger (PeriodicWorkRequest). */        const val TRIGGER_KIND_TIME = "time"        /** Event-based trigger (dynamic receiver fired). */        const val TRIGGER_KIND_EVENT = "event"        /** State-based trigger (dynamic receiver fired). */        const val TRIGGER_KIND_STATE = "state"        /** Compound trigger's child fired. */        const val TRIGGER_KIND_COMPOUND_CHILD = "compound_child"    }    override suspend fun doWork(): Result {        val ruleId = inputData.getString(KEY_RULE_ID) ?: run {            Timber.tag(TAG).e("No rule ID in input data — bailing.")            return Result.success()  // nothing we can do        }        val triggerKind = inputData.getString(KEY_TRIGGER_KIND) ?: TRIGGER_KIND_TIME        val engine = EntryPointAccessors.fromApplication(            applicationContext,            AutomationWorkerEntryPoint::class.java,        ).automationEngine()        val rule = engine.getRule(ruleId) ?: run {            Timber.tag(TAG).w("Rule $ruleId not found — likely deleted. Bailing.")            return Result.success()        }        if (!rule.isEnabled) {            Timber.tag(TAG).i("Rule '${rule.name}' (id=$ruleId) is disabled — skipping fire.")            return Result.success()        }        // Day-of-week filter for time triggers.        if (triggerKind == TRIGGER_KIND_TIME) {            val trigger = rule.trigger as? AutomationTrigger.TimeTrigger            if (trigger != null && !shouldFireToday(trigger)) {                Timber.tag(TAG).d("Rule '${rule.name}' — today is not a firing day. Skipping.")                return Result.success()            }        }        // Fire the rule.        val fireResult = if (triggerKind == TRIGGER_KIND_COMPOUND_CHILD) {            // Compound child fire — pass the trigger as the source.            // (The engine uses the sourceTrigger to record the fire in the            // compound trigger's history + evaluate the operator condition.)            engine.fireRule(ruleId, sourceTrigger = rule.trigger)        } else {            engine.fireRule(ruleId)        }        return when (fireResult) {            is FireResult.Fired -> {                Timber.tag(TAG).i("Rule '${rule.name}' (id=$ruleId) fired: ${fireResult.actionResult}")                Result.success()            }            is FireResult.Skipped -> {                Timber.tag(TAG).i("Rule '$ruleId' skipped: ${fireResult.reason}")                Result.success()            }            is FireResult.WaitingForCompound -> {                Timber.tag(TAG).d("Rule '$ruleId' waiting for compound condition.")                Result.success()            }        }    }    /**     * Check if a [AutomationTrigger.TimeTrigger] should fire today.     *     * Empty `daysOfWeek` set means "every day" (always returns true).     */    private fun shouldFireToday(trigger: AutomationTrigger.TimeTrigger): Boolean {        if (trigger.firesEveryDay) return true        val now = LocalDateTime.now()        val today = now.dayOfWeek        return today in trigger.daysOfWeek    }}/** * Hilt entry point for accessing [AutomationEngine] from non-Hilt code * (i.e., from [AutomationWorker] which is constructed by WorkManager). * * This avoids the need for a `HiltWorkerFactory` wired into the * `Application` class — a simpler pattern that matches how * [com.roshan.persona.productivity.reminder.ReminderWorker] accesses its * dependencies. */@EntryPoint@InstallIn(SingletonComponent::class)interface AutomationWorkerEntryPoint {    /** Access the singleton [AutomationEngine]. */    fun automationEngine(): AutomationEngine}/** * Helper to compute the current [DayOfWeek] from the device's default timezone. * * Not used in the worker itself (we use `LocalDateTime.now()` which already * uses the system default zone), but kept here for callers that need to * convert epoch millis → DayOfWeek in a specific timezone. */@Suppress("unused")private fun dayOfWeekFromEpoch(epochMillis: Long, zoneId: ZoneId = ZoneId.systemDefault()): DayOfWeek {    return java.time.Instant.ofEpochMilli(epochMillis)        .atZone(zoneId)        .dayOfWeek}